import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.BveOjhN0.js";const u=JSON.parse('{"title":"Companies Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Companies Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/companies-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Companies Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/companies-overview"}]]},"headers":[],"relativePath":"user-guide/companies-overview.md","filePath":"user-guide/companies-overview.md","lastUpdated":1785495358000}'),n={name:"user-guide/companies-overview.md"};function r(s,e,d,c,l,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="companies-module" tabindex="-1">Companies Module <a class="header-anchor" href="#companies-module" aria-label="Permalink to &quot;Companies Module&quot;">​</a></h1><p>CRM organizations module on the frozen platform. Mirrors the <a href="/user-guide/contacts-overview">Contacts</a> / <a href="/user-guide/leads-overview">Leads</a> reference architecture — a workspace directory of companies (organizations), with assignment, notes, and an activity timeline. Contacts can link to a Company via <code>company_id</code>.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/companies">companies.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/companies">companies-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/companies">companies-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/contacts-overview">contacts.md</a> · <a href="/user-guide/leads-overview">leads.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-companies">../api/tenant-v1-companies.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Name, email, phone, website, industry, address, source</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>companies.assign</code></li><li>Notes (comments) + activity timeline</li><li>Table view with search, industry filter, and <strong>My Companies</strong> toggle</li><li>Linked contacts shown on the company detail drawer</li><li>KPIs via <code>GET /companies/stats</code></li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:companies</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>companies.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Companies from Marketplace (free). Catalog: slug <code>companies</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 12</code>. Only Leads and Tasks install automatically on new workspaces.</p><h2 id="contact-linkage" tabindex="-1">Contact linkage <a class="header-anchor" href="#contact-linkage" aria-label="Permalink to &quot;Contact linkage&quot;">​</a></h2><p>When <strong>Companies</strong> is installed, Contact create/edit can pick a linked Company (<code>contacts.company_id</code>). The legacy free-text <code>company</code> string remains for display and search; when a Company is linked, that string is synced from the Company name. See <a href="/user-guide/contacts-overview">Contacts</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Lead convert-to-Company</li><li>Backfill job for legacy contact <code>company</code> strings → Company records</li><li>Meta invent Companies (inbound lead ads creating organizations)</li><li>Deals / opportunities linked to companies</li><li>Company import/export</li><li>Follow-ups (see <a href="/user-guide/leads-overview">Leads</a> for that pattern)</li></ul>',13)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
